"""Improved Express.js app with error handling, input validation, and security best practices."""

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const createError = require('http-errors');
const { param, validationResult } = require('express-validator');
const { StatusCodes } = require('http-status-codes');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: ['https://trusted-site.com'],
  methods: ['GET'],
}));

// Logging
app.use(morgan('combined'));

// Parse JSON bodies
app.use(express.json());

// Health check endpoint
app.get('/health', (req, res) => {
  res.status(StatusCodes.OK).json({
    status: 'ok', 
    timestamp: new Date().toISOString(),
  });
});

// Users endpoint with input validation
app.get('/users/:id',
  param('id').isInt().withMessage('ID must be an integer').escape(),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(StatusCodes.BAD_REQUEST).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(req.params.id));
    if (!user) {
      return next(createError(StatusCodes.NOT_FOUND, 'User not found'));
    }

    res.status(StatusCodes.OK).json(user);
  }
);

// List all users
app.get('/users', (req, res) => {
  res.status(StatusCodes.OK).json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler
app.use((req, res, next) => {
  next(createError(StatusCodes.NOT_FOUND, 'Route not found'));
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || StatusCodes.INTERNAL_SERVER_ERROR).json({
    error: 'Something went wrong!',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined,
  });
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

